ALTER TABLE ctf.projection_receipts DROP CONSTRAINT projection_receipts_kind_check;
ALTER TABLE ctf.projection_receipts ADD CONSTRAINT projection_receipts_kind_check CHECK(kind IN ('decision','catalog_mutation','config_mutation','owner_reset','owner_remove','global_reset','ban','unban','blocklist_clear','admit_attempt','record_blocked_attempt','register','start','hint','student_delete'));
CREATE FUNCTION ctf.ctf_deletion_receipt_matches(v jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT ctf.ctf_json_matches(v,'{"type":"object","properties":{"version":{"type":"number","enum":[3]},"kind":{"type":"string","enum":["student_delete"]},"operationId":{"type":"string","bytes":36,"pattern":"^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$"},"sequence":{"type":"string","bytes":19,"pattern":"^[1-9][0-9]*$","minimum":1,"maximum":"9223372036854775807"},"commandHash":{"type":"string","bytes":64,"pattern":"^[a-f0-9]{64}$"},"outcome":{"type":"string","enum":["applied"]},"data":{"type":"object","properties":{"jobId":{"type":"string","bytes":36,"pattern":"^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$"},"subjectId":{"type":"string","bytes":10,"pattern":"^[1-9][0-9]*$","minimum":1,"maximum":2147483647},"participantId":{"type":"string","bytes":10,"pattern":"^[1-9][0-9]*$","minimum":1,"maximum":2147483647,"nullable":true},"generationBefore":{"type":"string","bytes":19,"pattern":"^(0|[1-9][0-9]*)$","minimum":0,"maximum":"9223372036854775807"},"generationAfter":{"type":"string","bytes":19,"pattern":"^(0|[1-9][0-9]*)$","minimum":0,"maximum":"9223372036854775807"},"policyVersion":{"type":"string","enum":["ctf-student-delete-v1"]},"removed":{"type":"object","properties":{"bans":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"judgments":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"attempts":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"progress":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"techniques":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"leaderboard":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"events":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"sessions":{"type":"number","integer":true,"minimum":0,"maximum":2147483647},"participants":{"type":"number","integer":true,"minimum":0,"maximum":2147483647}}}}}}}'::jsonb) $$;
CREATE OR REPLACE FUNCTION ctf.valid_projection_result(v text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE WHEN v IS JSON OBJECT WITH UNIQUE KEYS THEN CASE WHEN v::jsonb->>'kind'='student_delete' THEN ctf.ctf_deletion_receipt_matches(v::jsonb) WHEN v::jsonb->>'kind'='decision' THEN ctf.ctf_decision_receipt_matches(v::jsonb) ELSE ctf.ctf_result_matches(v::jsonb) END ELSE false END $$;
REVOKE ALL ON FUNCTION ctf.ctf_deletion_receipt_matches(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ctf.ctf_deletion_receipt_matches(jsonb) TO dvaia_ctf_runtime;
